/**
 * Catálogos Latino + Streams — plugin único
 * TMDB: a2d9bbed370d9f678e34006f8750a5a5
 * OMDB: 5b0e8a3e, 1289a38c, eb1327da
 */

const TMDB_KEY = 'a2d9bbed370d9f678e34006f8750a5a5';
const OMDB_KEYS = ['5b0e8a3e', '1289a38c', 'eb1327da'];
const TMDB_BASE = 'https://api.themoviedb.org/3';
const IMG_BASE = 'https://image.tmdb.org/t/p';

const GENRE_MAP = {
  action: 28, adventure: 12, animation: 16, comedy: 35, crime: 80,
  documentary: 99, drama: 18, family: 10751, fantasy: 14, history: 36,
  horror: 27, music: 10402, mystery: 9648, romance: 10749,
  'science fiction': 878, 'sci-fi': 878, 'sci fi': 878, thriller: 53,
  war: 10752, western: 37, anime: 16, space: 878
};

function getConfig(key, def) {
  try {
    if (typeof config !== 'undefined' && config && config[key] != null) return config[key];
    if (typeof userConfig !== 'undefined' && userConfig && userConfig[key] != null) return userConfig[key];
  } catch (e) {}
  return def;
}

function tmdbLang() {
  return getConfig('tmdb_lang', 'es-ES') || 'es-ES';
}

function enabledSections() {
  const raw = getConfig('enabled_sections', 'Streaming Services,Discover,Genres,Decades,Directors,Franchises,Streaming');
  return String(raw).split(',').map(function (s) { return s.trim().toLowerCase(); }).filter(Boolean);
}

function hiddenCatalogs() {
  const raw = getConfig('hide_catalogs', '');
  return String(raw).split(',').map(function (s) { return s.trim().toLowerCase(); }).filter(Boolean);
}

async function tmdbFetch(path, params) {
  params = params || {};
  var qs = [];
  qs.push('api_key=' + encodeURIComponent(TMDB_KEY));
  qs.push('language=' + encodeURIComponent(tmdbLang()));
  for (var k in params) {
    if (params[k] != null && params[k] !== '') {
      qs.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(params[k])));
    }
  }
  var url = TMDB_BASE + path + '?' + qs.join('&');
  var res = await fetch(url);
  if (!res.ok) {
    var txt = '';
    try { txt = await res.text(); } catch (e) {}
    throw new Error('TMDB ' + res.status + ' ' + txt.slice(0, 120));
  }
  return res.json();
}

function posterUrl(path, size) {
  size = size || 'w342';
  if (!path) return null;
  if (String(path).indexOf('http') === 0) return path;
  return IMG_BASE + '/' + size + path;
}

function backdropUrl(path, size) {
  size = size || 'w780';
  if (!path) return null;
  if (String(path).indexOf('http') === 0) return path;
  return IMG_BASE + '/' + size + path;
}

function mapTmdbItem(item, typeHint) {
  var isTv = typeHint === 'tv' || typeHint === 'series' ||
    item.media_type === 'tv' ||
    (!!item.first_air_date && !item.release_date);
  var type = isTv ? 'series' : 'movie';
  var title = item.title || item.name || item.original_title || item.original_name || 'Sin título';
  var year = ((item.release_date || item.first_air_date || '') + '').slice(0, 4) || null;
  return {
    id: String(item.id),
    tmdbId: String(item.id),
    imdbId: item.imdb_id || null,
    title: title,
    name: title,
    poster: posterUrl(item.poster_path),
    posterPath: posterUrl(item.poster_path),
    backdrop: backdropUrl(item.backdrop_path),
    overview: item.overview || '',
    description: item.overview || '',
    type: type,
    media_type: type,
    rating: item.vote_average || null,
    vote_average: item.vote_average || null,
    year: year,
    genres: (item.genre_ids || []).map(String)
  };
}

function loadCatalogs() {
  if (typeof CATALOGS_DATA !== 'undefined' && CATALOGS_DATA && CATALOGS_DATA.length) {
    return CATALOGS_DATA;
  }
  return [];
}

function findFolder(catalogId) {
  var cid = String(catalogId || '').trim();
  var sections = loadCatalogs();
  for (var i = 0; i < sections.length; i++) {
    var sec = sections[i];
    var folders = sec.folders || [];
    for (var j = 0; j < folders.length; j++) {
      var f = folders[j];
      var fid = String(f.id || '').trim();
      var ftitle = String(f.title || '').trim();
      if (fid === cid || ftitle === cid ||
          fid.toLowerCase() === cid.toLowerCase() ||
          ftitle.toLowerCase() === cid.toLowerCase()) {
        return { folder: f, sectionTitle: sec.title || '' };
      }
    }
  }
  return { folder: null, sectionTitle: '' };
}

// ─── getHome ───────────────────────────────────────────────────────────────
async function getHome() {
  var sections = loadCatalogs();
  var enabled = enabledSections();
  var hidden = hiddenCatalogs();
  var rows = [];

  for (var i = 0; i < sections.length; i++) {
    var sec = sections[i];
    var st = (sec.title || '').toLowerCase();
    if (enabled.length && enabled.indexOf(st) === -1) continue;
    var items = [];
    var folders = sec.folders || [];
    for (var j = 0; j < folders.length; j++) {
      var folder = folders[j];
      var t = (folder.title || '').toLowerCase();
      var id = (folder.id || '').toLowerCase();
      var skip = false;
      for (var h = 0; h < hidden.length; h++) {
        if (t.indexOf(hidden[h]) !== -1 || id.indexOf(hidden[h]) !== -1) { skip = true; break; }
      }
      if (skip) continue;
      var catId = folder.id || folder.title;
      items.push({
        id: String(catId),
        title: folder.title,
        name: folder.title,
        poster: folder.cover || null,
        backdrop: folder.cover || null,
        type: 'catalog',
        overview: 'Catálogo: ' + folder.title,
        catalogId: String(catId)
      });
    }
    if (items.length) {
      rows.push({
        id: String(sec.id || sec.title),
        title: sec.title,
        type: 'row',
        imageStyle: 'backdrop',
        items: items
      });
    }
  }
  return { rows: rows };
}

// ─── getCatalogs ───────────────────────────────────────────────────────────
async function getCatalogs() {
  var sections = loadCatalogs();
  var enabled = enabledSections();
  var hidden = hiddenCatalogs();
  var list = [];
  for (var i = 0; i < sections.length; i++) {
    var sec = sections[i];
    var st = (sec.title || '').toLowerCase();
    if (enabled.length && enabled.indexOf(st) === -1) continue;
    var folders = sec.folders || [];
    for (var j = 0; j < folders.length; j++) {
      var folder = folders[j];
      var t = (folder.title || '').toLowerCase();
      var id = (folder.id || '').toLowerCase();
      var skip = false;
      for (var h = 0; h < hidden.length; h++) {
        if (t.indexOf(hidden[h]) !== -1 || id.indexOf(hidden[h]) !== -1) { skip = true; break; }
      }
      if (skip) continue;
      list.push({
        id: String(folder.id || folder.title),
        title: (sec.title || '') + ' › ' + folder.title,
        name: folder.title,
        poster: folder.cover || null,
        backdrop: folder.cover || null,
        description: 'Sección: ' + (sec.title || '')
      });
    }
  }
  return { catalogs: list };
}

// ─── resolve TMDB path from catalog title ──────────────────────────────────
function resolveTmdbQuery(title, sectionTitle, preferType) {
  title = (title || '').toLowerCase();
  sectionTitle = (sectionTitle || '').toLowerCase();
  var path = preferType === 'tv' ? '/tv/popular' : '/movie/popular';
  var params = {};

  if (/netflix|prime|disney|hbo|apple|paramount|hulu|max|peacock|crunchyroll/.test(title)) {
    path = preferType === 'tv' ? '/trending/tv/week' : '/trending/movie/week';
  } else if (/1980|1990|2000|2010|2020/.test(title)) {
    var m = title.match(/(1980|1990|2000|2010|2020)/);
    var y = m ? parseInt(m[1], 10) : 2010;
    path = '/discover/movie';
    params = {
      'primary_release_date.gte': y + '-01-01',
      'primary_release_date.lte': (y + 9) + '-12-31',
      sort_by: 'popularity.desc'
    };
  } else {
    var gkey = null;
    for (var g in GENRE_MAP) {
      if (title.indexOf(g) !== -1) { gkey = g; break; }
    }
    if (gkey) {
      path = preferType === 'tv' ? '/discover/tv' : '/discover/movie';
      params = { with_genres: String(GENRE_MAP[gkey]), sort_by: 'popularity.desc' };
    } else if (/trending|popular|descubrir|discover|novedad/.test(title) || /discover/.test(sectionTitle)) {
      path = '/trending/all/week';
    } else if (/director|anderson|nolan|spielberg|tarantino|scorsese|kubrick|cameron|burton|coen|boyle|howard|scott|shyamalan|stone/.test(title)) {
      path = '/discover/movie';
      params = { sort_by: 'popularity.desc', 'primary_release_date.gte': '1970-01-01' };
    } else if (/franchise|star wars|marvel|harry potter|middle earth|john wick|jurassic|alien|terminator|matrix|avatar/.test(title)) {
      path = '/trending/all/week';
    }
  }
  return { path: path, params: params };
}

// ─── getCatalog (página individual del catálogo) ────────────────────────────
async function getCatalog(catalogId, opts) {
  opts = opts || {};
  var page = 1;
  if (typeof opts === 'object') {
    page = parseInt(opts.page || opts.skip || 1, 10) || 1;
  } else if (typeof opts === 'number') {
    page = opts;
  }

  var found = findFolder(catalogId);
  var folder = found.folder;
  var sectionTitle = found.sectionTitle;
  var title = (folder && folder.title) || String(catalogId || '');
  var sources = (folder && folder.sources) || [];
  var preferType = 'movie';
  for (var i = 0; i < sources.length; i++) {
    if (sources[i].type === 'series' || sources[i].type === 'tv') { preferType = 'tv'; break; }
  }

  var q = resolveTmdbQuery(title, sectionTitle, preferType);
  var params = Object.assign({}, q.params, { page: String(page) });

  try {
    var data = await tmdbFetch(q.path, params);
    var results = (data.results || []).map(function (r) {
      return mapTmdbItem(r, r.media_type || preferType);
    });

    // Si vacío, fallback popular
    if (!results.length) {
      var fb = preferType === 'tv' ? '/tv/popular' : '/movie/popular';
      data = await tmdbFetch(fb, { page: String(page) });
      results = (data.results || []).map(function (r) {
        return mapTmdbItem(r, preferType);
      });
    }

    var totalPages = data.total_pages || 1;
    var curPage = data.page || page;
    return {
      items: results,
      metas: results,
      results: results,
      page: curPage,
      totalPages: totalPages,
      hasMore: curPage < totalPages
    };
  } catch (e) {
    // Último recurso
    try {
      var data2 = await tmdbFetch('/trending/all/week', { page: String(page) });
      var results2 = (data2.results || []).map(function (r) { return mapTmdbItem(r); });
      return { items: results2, metas: results2, results: results2, page: page, totalPages: 1, hasMore: false };
    } catch (e2) {
      return { items: [], metas: [], results: [], page: page, totalPages: 1, hasMore: false, error: String(e) };
    }
  }
}

// ─── getDiscover (pestaña Descubrir — OBLIGATORIO) ─────────────────────────
async function getDiscover(opts) {
  opts = opts || {};
  var page = parseInt(opts.page || 1, 10) || 1;
  var filter = (opts.filter || opts.genre || opts.type || '').toString().toLowerCase();

  var path = '/trending/all/week';
  var params = { page: String(page) };

  if (filter === 'movie' || filter === 'movies' || filter === 'peliculas' || filter === 'películas') {
    path = '/movie/popular';
  } else if (filter === 'tv' || filter === 'series' || filter === 'show') {
    path = '/tv/popular';
  } else if (GENRE_MAP[filter]) {
    path = '/discover/movie';
    params.with_genres = String(GENRE_MAP[filter]);
    params.sort_by = 'popularity.desc';
  }

  try {
    var data = await tmdbFetch(path, params);
    var results = (data.results || []).map(function (r) {
      return mapTmdbItem(r, r.media_type);
    });
    if (!results.length) {
      data = await tmdbFetch('/movie/popular', { page: String(page) });
      results = (data.results || []).map(function (r) { return mapTmdbItem(r, 'movie'); });
    }
    var totalPages = data.total_pages || 1;
    var curPage = data.page || page;
    return {
      items: results,
      metas: results,
      results: results,
      page: curPage,
      totalPages: totalPages,
      hasMore: curPage < totalPages
    };
  } catch (e) {
    return { items: [], metas: [], results: [], page: page, totalPages: 1, hasMore: false, error: String(e) };
  }
}

async function getDiscoverFilters() {
  return [
    { id: 'all', title: 'Todo' },
    { id: 'movie', title: 'Películas' },
    { id: 'tv', title: 'Series' },
    { id: 'action', title: 'Acción' },
    { id: 'comedy', title: 'Comedia' },
    { id: 'horror', title: 'Terror' },
    { id: 'drama', title: 'Drama' },
    { id: 'romance', title: 'Romance' },
    { id: 'thriller', title: 'Suspense' },
    { id: 'animation', title: 'Animación' }
  ];
}

// ─── getMeta ───────────────────────────────────────────────────────────────
async function omdbToTmdb(imdbId) {
  if (!imdbId) return null;
  var id = String(imdbId).indexOf('tt') === 0 ? imdbId : 'tt' + imdbId;
  for (var i = 0; i < OMDB_KEYS.length; i++) {
    try {
      var res = await fetch('https://www.omdbapi.com/?i=' + encodeURIComponent(id) + '&apikey=' + OMDB_KEYS[i]);
      var data = await res.json();
      if (data && data.Response === 'True' && data.imdbID) {
        var find = await tmdbFetch('/find/' + data.imdbID, { external_source: 'imdb_id' });
        var movie = (find.movie_results || [])[0];
        var tv = (find.tv_results || [])[0];
        if (movie) return { tmdbId: String(movie.id), type: 'movie' };
        if (tv) return { tmdbId: String(tv.id), type: 'tv' };
      }
    } catch (e) {}
  }
  return null;
}

async function getMeta(id, type) {
  var tmdbId = id;
  var mediaType = (type === 'series' || type === 'tv' || type === 'show') ? 'tv' : 'movie';

  if (String(id).indexOf('tt') === 0 || (!/^\d+$/.test(String(id)) && String(id).length > 5)) {
    var conv = await omdbToTmdb(id);
    if (conv) {
      tmdbId = conv.tmdbId;
      mediaType = conv.type === 'tv' ? 'tv' : 'movie';
    }
  }

  try {
    var data = await tmdbFetch('/' + mediaType + '/' + tmdbId, {
      append_to_response: 'credits,external_ids,videos,images,recommendations'
    });
    var isTv = mediaType === 'tv';
    var title = data.title || data.name || 'Sin título';
    var year = ((data.release_date || data.first_air_date || '') + '').slice(0, 4);
    var genres = (data.genres || []).map(function (g) { return g.name; });
    var imdb = (data.external_ids && data.external_ids.imdb_id) || null;

    var logo = null;
    try {
      var logos = ((data.images && data.images.logos) || []).filter(function (l) { return l.file_path; });
      logos.sort(function (a, b) {
        function score(l) {
          var s = 0;
          if (l.iso_639_1 === 'es' || l.iso_639_1 === 'es-ES' || l.iso_639_1 === 'es-MX') s += 10;
          else if (l.iso_639_1 === 'en' || !l.iso_639_1) s += 5;
          if (l.aspect_ratio >= 1.5 && l.aspect_ratio <= 4) s += 3;
          return s;
        }
        return score(b) - score(a);
      });
      if (logos.length) logo = posterUrl(logos[0].file_path, 'w500');
    } catch (e) {}

    var seasons = [];
    if (isTv && data.seasons) {
      seasons = data.seasons
        .filter(function (s) { return s.season_number > 0; })
        .map(function (s) {
          return {
            season: s.season_number,
            number: s.season_number,
            title: s.name || ('Temporada ' + s.season_number),
            name: s.name || ('Temporada ' + s.season_number),
            episodeCount: s.episode_count,
            poster: posterUrl(s.poster_path),
            overview: s.overview || '',
            episodes: []
          };
        });

      var toFetch = seasons.slice(0, 5);
      await Promise.all(toFetch.map(async function (sObj) {
        try {
          var seasonData = await tmdbFetch('/tv/' + tmdbId + '/season/' + sObj.season);
          sObj.episodes = (seasonData.episodes || []).map(function (ep) {
            return {
              episode: ep.episode_number,
              number: ep.episode_number,
              title: ep.name || ('Episodio ' + ep.episode_number),
              name: ep.name || ('Episodio ' + ep.episode_number),
              overview: ep.overview || '',
              still: posterUrl(ep.still_path, 'w300'),
              backdrop: posterUrl(ep.still_path, 'w780'),
              runtime: ep.runtime || null,
              airDate: ep.air_date || null,
              rating: ep.vote_average || null
            };
          });
          sObj.episodeCount = sObj.episodes.length || sObj.episodeCount;
        } catch (e) {}
      }));
    }

    return {
      id: String(tmdbId),
      tmdbId: String(tmdbId),
      imdbId: imdb,
      title: title,
      name: title,
      poster: posterUrl(data.poster_path, 'w500'),
      backdrop: backdropUrl(data.backdrop_path, 'w1280'),
      logo: logo,
      overview: data.overview || '',
      description: data.overview || '',
      type: isTv ? 'series' : 'movie',
      rating: data.vote_average,
      year: year,
      genres: genres,
      seasons: seasons,
      runtime: data.runtime || (data.episode_run_time && data.episode_run_time[0]) || null,
      status: data.status,
      extra: { tagline: data.tagline, logo: logo }
    };
  } catch (e) {
    return { id: String(id), title: 'Error', overview: String(e), type: mediaType === 'tv' ? 'series' : 'movie' };
  }
}

// ─── search ────────────────────────────────────────────────────────────────
async function search(query, opts) {
  if (!query || !String(query).trim()) return { items: [] };
  opts = opts || {};
  var page = parseInt(opts.page || 1, 10) || 1;
  try {
    var data = await tmdbFetch('/search/multi', { query: String(query).trim(), page: String(page) });
    var items = (data.results || [])
      .filter(function (r) { return r.media_type === 'movie' || r.media_type === 'tv'; })
      .map(function (r) { return mapTmdbItem(r, r.media_type); });
    return { items: items, metas: items, results: items, page: data.page, totalPages: data.total_pages };
  } catch (e) {
    return { items: [], metas: [], results: [] };
  }
}

// ─── getStreams (5 fuentes embebidas) ──────────────────────────────────────
var PRIORITY_SOURCES = [
  { id: 'embed69', name: 'Embed69' },
  { id: 'vimeus', name: 'Vimeus' },
  { id: 'lamovie', name: 'LaMovie' },
  { id: 'elifilms', name: 'EliFilms' },
  { id: 'homecine', name: 'HomeCine' }
];

function getEnabledSources() {
  var raw = getConfig('enabled_sources', 'embed69,vimeus,lamovie,elifilms,homecine');
  var wanted = String(raw).toLowerCase().split(/[,;\s]+/).map(function (s) { return s.trim(); }).filter(Boolean);
  return PRIORITY_SOURCES.filter(function (s) {
    return wanted.indexOf(s.id) !== -1 || wanted.indexOf(s.name.toLowerCase()) !== -1;
  });
}

function getMaxConcurrent() {
  var n = parseInt(getConfig('max_concurrent_sources', '3'), 10);
  return Math.max(1, Math.min(5, isNaN(n) ? 3 : n));
}

function normalizeStream(s, sourceName) {
  if (!s) return null;
  var url = (s.url || s.file || s.src || s.link || s.stream || '').toString().trim();
  if (!url || url.indexOf('http') !== 0) return null;
  var lower = url.toLowerCase();
  return {
    name: s.name || s.title || sourceName,
    title: (s.title || s.name || sourceName) + (s.quality ? ' [' + s.quality + ']' : ''),
    url: url,
    quality: s.quality || s.q || 'HD',
    language: s.language || s.lang || 'Latino',
    server: s.server || sourceName,
    isHls: /\.m3u8|hls|manifest/i.test(lower),
    isMp4: /\.mp4/i.test(lower),
    source: sourceName
  };
}

async function fetchText(url) {
  var res = await fetch(url, {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Accept': 'text/html,application/xhtml+xml',
      'Accept-Language': 'es-ES,es;q=0.9'
    },
    redirect: 'follow'
  });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return res.text();
}

function extractEmbeds(html) {
  var urls = {};
  var patterns = [
    /(?:src|href|data-src|data-url)=["'](https?:\/\/[^"']+(?:\.m3u8|\.mp4|embed|player|voe|streamwish|filemoon|dood|upstream|mixdrop|vidhide)[^"']*)["']/gi,
    /["'](https?:\/\/[^"']+\.m3u8[^"']*)["']/gi,
    /["'](https?:\/\/[^"']+\.mp4[^"']*)["']/gi,
    /file\s*:\s*["'](https?:\/\/[^"']+)["']/gi
  ];
  for (var p = 0; p < patterns.length; p++) {
    var re = patterns[p];
    var m;
    while ((m = re.exec(html)) !== null) {
      var u = (m[1] || m[0] || '').replace(/&amp;/g, '&');
      if (u.indexOf('http') === 0 && u.indexOf('google') === -1) urls[u] = true;
    }
  }
  return Object.keys(urls);
}

async function tryUrls(candidates, serverName) {
  var streams = [];
  for (var i = 0; i < candidates.length; i++) {
    try {
      var html = await fetchText(candidates[i]);
      var embeds = extractEmbeds(html);
      for (var j = 0; j < embeds.length; j++) {
        streams.push({ url: embeds[j], quality: 'HD', language: 'Latino', server: serverName });
      }
      if (streams.length) break;
    } catch (e) {}
  }
  return streams;
}

async function extractEmbed69(tmdbId, mediaType, season, episode, meta) {
  var title = (meta && meta.title) || '';
  var year = (meta && meta.year) || '';
  var slug = (title + (year ? '-' + year : '')).toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-');
  return tryUrls([
    'https://embed69.org/movies/' + slug,
    'https://embed69.org/movie/' + tmdbId,
    'https://embed69.org/tv/' + tmdbId
  ], 'Embed69');
}

async function extractVimeus(tmdbId, mediaType, season, episode, meta) {
  var title = (meta && meta.title) || '';
  var year = (meta && meta.year) || '';
  var q = encodeURIComponent(title + (year ? ' ' + year : ''));
  return tryUrls([
    'https://vimeus.com/search?q=' + q,
    'https://vimeus.com/movie/' + tmdbId
  ], 'Vimeus');
}

async function extractLaMovie(tmdbId, mediaType, season, episode, meta) {
  var title = (meta && meta.title) || '';
  var year = (meta && meta.year) || '';
  var slug = (title + (year ? '-' + year : '')).toLowerCase().replace(/[^a-z0-9]+/g, '-');
  return tryUrls([
    'https://lamovie.org/movie/' + slug,
    'https://lamovie.org/?s=' + encodeURIComponent(title)
  ], 'LaMovie');
}

async function extractEliFilms(tmdbId, mediaType, season, episode, meta) {
  var title = (meta && meta.title) || '';
  var q = encodeURIComponent(title);
  return tryUrls([
    'https://allcalidad.re/?s=' + q,
    'https://elifilms.net/?s=' + q
  ], 'EliFilms');
}

async function extractHomeCine(tmdbId, mediaType, season, episode, meta) {
  var title = (meta && meta.title) || '';
  var year = (meta && meta.year) || '';
  var slug = (title + (year ? '-' + year : '')).toLowerCase().replace(/[^a-z0-9]+/g, '-');
  return tryUrls([
    'https://homecine.to/movies/' + slug,
    'https://homecine.to/?s=' + encodeURIComponent(title)
  ], 'HomeCine');
}

var EXTRACTORS = {
  embed69: extractEmbed69,
  vimeus: extractVimeus,
  lamovie: extractLaMovie,
  elifilms: extractEliFilms,
  homecine: extractHomeCine
};

async function runWithConcurrency(tasks, limit) {
  var results = [];
  var executing = [];
  for (var i = 0; i < tasks.length; i++) {
    (function (task) {
      var p = Promise.resolve().then(task).then(function (r) {
        executing = executing.filter(function (x) { return x !== p; });
        return r;
      }).catch(function () {
        executing = executing.filter(function (x) { return x !== p; });
        return [];
      });
      results.push(p);
      executing.push(p);
    })(tasks[i]);
    if (executing.length >= limit) {
      await Promise.race(executing);
    }
  }
  return Promise.all(results);
}

async function getStreams(id, type, season, episode) {
  var tmdbId = id;
  var imdbId = null;
  var mediaType = (type === 'series' || type === 'tv' || type === 'show') ? 'tv' : 'movie';

  if (String(id).indexOf('tt') === 0) {
    var conv = await omdbToTmdb(id);
    if (conv) {
      tmdbId = conv.tmdbId;
      mediaType = conv.type === 'tv' ? 'tv' : 'movie';
    }
    imdbId = String(id);
  } else {
    try {
      var ext = await tmdbFetch('/' + mediaType + '/' + tmdbId + '/external_ids');
      imdbId = ext.imdb_id || null;
    } catch (e) {}
  }

  var meta = { title: '', year: '' };
  try {
    var m = await tmdbFetch('/' + mediaType + '/' + tmdbId);
    meta.title = m.title || m.name || '';
    meta.year = ((m.release_date || m.first_air_date || '') + '').slice(0, 4);
  } catch (e) {}

  var sources = getEnabledSources();
  var limit = getMaxConcurrent();
  var tasks = sources.map(function (src) {
    return async function () {
      var fn = EXTRACTORS[src.id];
      if (!fn) return [];
      try {
        var raw = await fn(tmdbId, mediaType, season, episode, meta);
        return (raw || []).map(function (s) { return normalizeStream(s, src.name); }).filter(Boolean);
      } catch (e) {
        return [];
      }
    };
  });

  var batches = await runWithConcurrency(tasks, limit);
  var allStreams = [];
  var seen = {};
  for (var i = 0; i < batches.length; i++) {
    var list = batches[i] || [];
    for (var j = 0; j < list.length; j++) {
      var s = list[j];
      var key = s.url.split('?')[0];
      if (seen[key]) continue;
      seen[key] = true;
      allStreams.push(s);
    }
  }

  allStreams.sort(function (a, b) {
    if (a.isHls && !b.isHls) return -1;
    if (!a.isHls && b.isHls) return 1;
    return 0;
  });

  return allStreams;
}

// Export
var addon = {
  getHome: getHome,
  getCatalogs: getCatalogs,
  getCatalog: getCatalog,
  getDiscover: getDiscover,
  getDiscoverFilters: getDiscoverFilters,
  getMeta: getMeta,
  search: search,
  getStreams: getStreams
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = addon;
}
if (typeof globalThis !== 'undefined') {
  globalThis.getHome = getHome;
  globalThis.getCatalogs = getCatalogs;
  globalThis.getCatalog = getCatalog;
  globalThis.getDiscover = getDiscover;
  globalThis.getDiscoverFilters = getDiscoverFilters;
  globalThis.getMeta = getMeta;
  globalThis.search = search;
  globalThis.getStreams = getStreams;
}
